window.EKAGRA.calcFee = function calcFee(input, data) {
  var stage = input.stage, goal = input.goal, mode = input.mode;
  var schol = Number(input.schol) || 0;
  var plan = input.plan || 'full';
  var sibling = !!input.sibling;
  var row = data.feeMatrix[stage][goal];
  var m = data.modes.find(function (x) { return x.id === mode; }) || data.modes[0];
  var r = data.feeRules;

  var tuition = Math.round((row.tuition * m.factor) / 100) * 100;
  var scholAmt = Math.round((tuition * schol) / 100);
  var afterSchol = tuition - scholAmt;
  var siblingAmt = sibling ? Math.round((afterSchol * r.siblingPct) / 100) : 0;
  var afterSibling = afterSchol - siblingAmt;
  var fullAmt = plan === 'full' ? Math.round((afterSibling * r.fullPaymentPct) / 100) : 0;

  // Combined discounts never exceed the cap; trim the full-payment discount first, then the sibling discount.
  var cap = Math.round((tuition * r.maxDiscountPct) / 100);
  var over = scholAmt + siblingAmt + fullAmt - cap;
  if (over > 0) {
    var cut = Math.min(fullAmt, over);
    fullAmt -= cut;
    over -= cut;
    siblingAmt -= Math.min(siblingAmt, over);
  }

  var discount = scholAmt + siblingAmt + fullAmt;
  var material = row.material;
  var subtotal = tuition - discount + material;
  var gst = Math.round(subtotal * r.gst);
  var total = subtotal + gst;

  var instalments;
  if (plan === 'full') {
    instalments = [{ label: 'At admission', amount: total }];
  } else if (plan === 'two') {
    var first = Math.round(total * 0.6);
    instalments = [
      { label: 'At admission', amount: first },
      { label: 'By ' + r.secondInstalmentDue, amount: total - first },
    ];
  } else {
    var per = Math.floor(total / 10);
    instalments = [];
    for (var i = 0; i < 10; i++) instalments.push({ label: 'Month ' + (i + 1), amount: i === 9 ? total - per * 9 : per });
  }

  return {
    row: row,
    mode: m,
    tuition: tuition,
    scholPct: schol,
    scholAmt: scholAmt,
    siblingAmt: siblingAmt,
    fullAmt: fullAmt,
    material: material,
    subtotal: subtotal,
    gst: gst,
    total: total,
    years: row.years,
    courseTotal: total * row.years,
    instalments: instalments,
  };
};
